uint32_t h1 = ckh_hash1(key);
uint32_t h2 = ckh_hash2(key);
uint32_t pos1 = h1 % ckh->capacity;
uint32_t pos2 = h2 % ckh->capacity;

if (ckh->buckets[pos1].key == key) {
    ckh->buckets[pos1].data = data;
    return false;
}
if (ckh->buckets[pos2].key == key) {
    ckh->buckets[pos2].data = data;
    return false;
}

if (ckh->buckets[pos1].key == nullptr) {
    ckh->buckets[pos1].key = (void*)key;
    ckh->buckets[pos1].data = data;
    return false;
}
if (ckh->buckets[pos2].key == nullptr) {
    ckh->buckets[pos2].key = (void*)key;
    ckh->buckets[pos2].data = data;
    return false;
}

const void *curr_key = key;
const void *curr_data = data;
uint32_t curr_pos = pos1;

for (int i = 0; i < ckh->max_evictions; ++i) {
    std::swap(curr_key, ckh->buckets[curr_pos].key);
    std::swap(curr_data, ckh->buckets[curr_pos].data);

    if (curr_key == nullptr) {
        return false;
    }

    uint32_t kh1 = ckh_hash1(curr_key) % ckh->capacity;
    uint32_t kh2 = ckh_hash2(curr_key) % ckh->capacity;
    curr_pos = (curr_pos == kh1) ? kh2 : kh1;

    if (ckh->buckets[curr_pos].key == nullptr) {
        ckh->buckets[curr_pos].key = (void*)curr_key;
        ckh->buckets[curr_pos].data = curr_data;
        return false;
    }
}

return true;
// END_CODE

